// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0) && actor != address(this) && actor != address(c));
        bytes32 role = c.PROPOSER_ROLE();

        // grant the role to the fuzzed actor via admin (the test contract deployer)
        c.grantRole(role, actor);
        assertTrue(c.hasRole(role, actor), "precondition: actor holds role");

        // actor renounces its own role for itself
        vm.prank(actor);
        bool ok;
        try c.renounceRole(role, actor) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && !c.hasRole(role, actor), "self-renounce must succeed and drop the role");
    }
}
